INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10501, 'ក្នុងសំណុំចំនួនកុំផ្លិច \(\mathbb{C}\) តម្លៃនៃឯកតានិម្មិត \(i^2\) ស្មើនឹង៖', NULL, '["\\(0\\)", "\\(-i\\)", "\\(-1\\)", "\\(1\\)"]', 2, NULL, 1, 'mcq', 'តាមនិយមន័យនៃឯកតានិម្មិត \(i\) គេមាន \(i^2 = -1\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'easy', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10502, 'កំណត់ផ្នែកពិត និងផ្នែកនិម្មិតនៃចំនួនកុំផ្លិច \(z = 4 - 7i\)៖', NULL, '["\\(\\operatorname{Re}(z) = -7, \\operatorname{Im}(z) = 4\\)", "\\(\\operatorname{Re}(z) = 4, \\operatorname{Im}(z) = -7\\)", "\\(\\operatorname{Re}(z) = 4, \\operatorname{Im}(z) = 7\\)", "\\(\\operatorname{Re}(z) = 4, \\operatorname{Im}(z) = -7i\\)"]', 1, NULL, 1, 'mcq', 'ចំពោះ \(z = a + bi\) គេបានផ្នែកពិត \(\operatorname{Re}(z) = a = 4\) និងផ្នែកនិម្មិត \(\operatorname{Im}(z) = b = -7\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'easy', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10503, 'ចំនួនកុំផ្លិចឆ្លាស់នៃ \(z = 3 + 5i\) គឺ៖', NULL, '["\\(\\bar{z} = 3 - 5i\\)", "\\(\\bar{z} = -3 + 5i\\)", "\\(\\bar{z} = -3 - 5i\\)", "\\(\\bar{z} = 5 + 3i\\)"]', 0, NULL, 1, 'mcq', 'កុំផ្លិចឆ្លាស់នៃ \(z = a + bi\) គឺ \(\bar{z} = a - bi\) ដូច្នេះ \(\bar{z} = 3 - 5i\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'easy', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10504, 'ម៉ូឌុលនៃចំនួនកុំផ្លិច \(z = 3 + 4i\) ស្មើនឹង៖', NULL, '["\\(5\\)", "\\(7\\)", "\\(25\\)", "\\(\\sqrt{7}\\)"]', 0, NULL, 1, 'mcq', 'ម៉ូឌុលកំណត់ដោយ \(|z| = \sqrt{a^2 + b^2} = \sqrt{3^2 + 4^2} = \sqrt{9 + 16} = \sqrt{25} = 5\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'easy', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10505, 'រូបមន្តឌីសគ្រីមីណង់ \(\Delta\) នៃសមីការដឺក្រេទីពីរ \(ax^2 + bx + c = 0\) (\(a \neq 0\)) គឺ៖', NULL, '["\\(\\Delta = b^2 - 2ac\\)", "\\(\\Delta = 4ac - b^2\\)", "\\(\\Delta = b^2 - 4ac\\)", "\\(\\Delta = b^2 + 4ac\\)"]', 2, NULL, 1, 'mcq', 'ឌីសគ្រីមីណង់នៃសមីការដឺក្រេទីពីរគឺ \(\Delta = b^2 - 4ac\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'easy', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10506, 'បើឌីសគ្រីមីណង់ \(\Delta > 0\) នោះសមីការដឺក្រេទីពីរមាន៖', NULL, '["ឫសឌុបជាចំនួនពិត", "ឫសមួយជាសូន្យជានិច្ច", "ឫសពីរជាចំនួនកុំផ្លិចឆ្លាស់គ្នា", "ឫសពីរជាចំនួនពិតខុសគ្នា"]', 3, NULL, 1, 'mcq', 'កាលណា \(\Delta > 0\) សមីការមានឫសពីរជាចំនួនពិតខុសគ្នា \(x_1, x_2 = \dfrac{-b \pm \sqrt{\Delta}}{2a}\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'easy', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10507, 'បើ \(\Delta = 0\) នោះឫសឌុបនៃសមីការ \(ax^2 + bx + c = 0\) កំណត់ដោយ៖', NULL, '["\\(x_1 = x_2 = -\\dfrac{c}{a}\\)", "\\(x_1 = x_2 = -\\dfrac{b}{2a}\\)", "\\(x_1 = x_2 = \\dfrac{b}{2a}\\)", "\\(x_1 = x_2 = -\\dfrac{b}{a\\)"]', 1, NULL, 1, 'mcq', 'កាលណា \(\Delta = 0\) ឫសឌុបគឺ \(x_0 = -\dfrac{b}{2a}\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'easy', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10508, 'រកសំណុំចម្លើយនៃសមីការ \(x^2 - 16 = 0\) ក្នុង \(\mathbb{R}\)៖', NULL, '["\\(x = 4 \\text{ ឬ } x = -4\\)", "\\(x = 8 \\text{ ឬ } x = -8\\)", "\\(x = 4 \\text{ តែមួយគត់}\\)", "\\(x = 16 \\text{ ឬ } x = -16\\)"]', 0, NULL, 1, 'mcq', '\(x^2 = 16 \implies x = \pm \sqrt{16} = \pm 4\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'easy', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10509, 'បើ \(x_1\) និង \(x_2\) ជាឫសនៃសមីការ \(ax^2 + bx + c = 0\) នោះផលបូកឫស \(S = x_1 + x_2\) ស្មើនឹង៖', NULL, '["\\(\\dfrac{c}{a}\\)", "\\(-\\dfrac{b}{a}\\)", "\\(\\dfrac{b}{a}\\)", "\\(-\\dfrac{c}{a}\\)"]', 1, NULL, 1, 'mcq', 'តាមរូបមន្តវីយែត ផលបូកឫសគឺ \(S = x_1 + x_2 = -\dfrac{b}{a}\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'easy', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10510, 'បើ \(x_1\) និង \(x_2\) ជាឫសនៃសមីការ \(ax^2 + bx + c = 0\) នោះផលគុណឫស \(P = x_1 x_2\) ស្មើនឹង៖', NULL, '["\\(-\\dfrac{b}{a}\\)", "\\(\\dfrac{c}{a}\\)", "\\(\\dfrac{b}{a}\\)", "\\(-\\dfrac{c}{a}\\)"]', 1, NULL, 1, 'mcq', 'តាមរូបមន្តវីយែត ផលគុណឫសគឺ \(P = x_1 x_2 = \dfrac{c}{a}\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'easy', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10511, 'គណនាតម្លៃនៃកន្សោម \((3 + 4i) + (2 - 6i) - (1 - i)\)៖', NULL, '["\\(4 + i\\)", "\\(6 - 3i\\)", "\\(4 - i\\)", "\\(4 - 3i\\)"]', 2, NULL, 2, 'mcq', 'បូកផ្នែកពិត និងផ្នែកនិម្មិតរៀងៗខ្លួន៖ \((3 + 2 - 1) + (4 - 6 - (-1))i = 4 - i\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10512, 'គណនាផលគុណនៃពីរចំនួនកុំផ្លិច \((2 + 3i)(4 - i)\)៖', NULL, '["\\(8 - 3i\\)", "\\(5 + 10i\\)", "\\(11 + 10i\\)", "\\(11 - 10i\\)"]', 2, NULL, 2, 'mcq', '\((2)(4) + (2)(-i) + (3i)(4) + (3i)(-i) = 8 - 2i + 12i - 3(-1) = 8 + 10i + 3 = 11 + 10i\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10513, 'សរសេរកន្សោមផលចែក \(\dfrac{5 + 5i}{1 + 2i}\) ជាទម្រង់ពីជគណិត \(a + bi\)៖', NULL, '["\\(3 - i\\)", "\\(1 - 3i\\)", "\\(3 + i\\)", "\\(5 - i\\)"]', 0, NULL, 2, 'mcq', 'គុណភាគយក និងភាគបែងនឹង \(1 - 2i\)៖ \(\dfrac{(5+5i)(1-2i)}{1^2 - (2i)^2} = \dfrac{5 - 10i + 5i + 10}{1 + 4} = \dfrac{15 - 5i}{5} = 3 - i\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10514, 'គណនាតម្លៃនៃស្វ័យគុណ \(i^{2\,026}\)៖', NULL, '["\\(1\\)", "\\(i\\)", "\\(-i\\)", "\\(-1\\)"]', 3, NULL, 2, 'mcq', '\(2\,026 = 4 \times 506 + 2\) ដូច្នេះ \(i^{2\,026} = (i^4)^{506} \times i^2 = 1^{506} \times (-1) = -1\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10515, 'រកសំណុំចម្លើយនៃសមីការ \(x^2 - 7x + 12 = 0\) ដោយដាក់ជាផលគុណកត្តា៖', NULL, '["\\(S = \\{-3, 4\\}\\)", "\\(S = \\{-3, -4\\}\\)", "\\(S = \\{3, 4\\}\\)", "\\(S = \\{2, 6\\}\\)"]', 2, NULL, 2, 'mcq', '\(x^2 - 7x + 12 = (x - 3)(x - 4) = 0 \implies x = 3\) ឬ \(x = 4\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10516, 'រកឫសនៃសមីការ \(2x^2 - 5x + 2 = 0\)៖', NULL, '["\\(x = -2 \\text{ ឬ } x = -\\dfrac{1}{2}\\)", "\\(x = 1 \\text{ ឬ } x = \\dfrac{5}{2}\\)", "\\(x = 2 \\text{ ឬ } x = \\dfrac{1}{2}\\)", "\\(x = 3 \\text{ ឬ } x = \\dfrac{1}{4}\\)"]', 2, NULL, 2, 'mcq', '\(\Delta = (-5)^2 - 4(2)(2) = 25 - 16 = 9 \implies x = \dfrac{5 \pm 3}{4}\) នាំឱ្យ \(x = 2\) ឬ \(x = \dfrac{1}{2}\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10517, 'ប្រើឌីសគ្រីមីណង់សម្រួល \(\Delta''\) ដើម្បីដោះស្រាយសមីការ \(x^2 - 6x + 7 = 0\)៖', NULL, '["\\(x = 3 \\pm 2\\sqrt{2}\\)", "\\(x = 3 \\pm \\sqrt{2}\\)", "\\(x = -3 \\pm \\sqrt{2}\\)", "\\(x = 6 \\pm \\sqrt{2}\\)"]', 1, NULL, 2, 'mcq', '\(b'' = -3, \Delta'' = (-3)^2 - 1(7) = 9 - 7 = 2 \implies x = 3 \pm \sqrt{2}\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10518, 'រកឫសនៃសមីការ \(x^2 + 2x + 5 = 0\) ក្នុងសំណុំចំនួនកុំផ្លិច \(\mathbb{C}\)៖', NULL, '["\\(x = -2 \\pm i\\)", "\\(x = 1 \\pm 2i\\)", "\\(x = -1 \\pm 2i\\)", "\\(x = -1 \\pm 4i\\)"]', 2, NULL, 2, 'mcq', '\(b'' = 1, \Delta'' = 1^2 - 1(5) = -4 = (2i)^2 \implies x = -1 \pm 2i\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10519, 'បើ \(x_1\) និង \(x_2\) ជាឫសនៃសមីការ \(x^2 - 5x + 3 = 0\) គណនា \(x_1^2 + x_2^2\)៖', NULL, '["\\(22\\)", "\\(25\\)", "\\(19\\)", "\\(16\\)"]', 2, NULL, 2, 'mcq', '\(S = 5, P = 3 \implies x_1^2 + x_2^2 = S^2 - 2P = 5^2 - 2(3) = 25 - 6 = 19\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10520, 'បើ \(x_1\) និង \(x_2\) ជាឫសនៃសមីការ \(2x^2 + 6x - 3 = 0\) គណនា \(\dfrac{1}{x_1} + \dfrac{1}{x_2}\)៖', NULL, '["\\(\\dfrac{1}{2}\\)", "\\(2\\)", "\\(-\\dfrac{1}{2}\\)", "\\(-2\\)"]', 1, NULL, 2, 'mcq', '\(S = -\dfrac{6}{2} = -3, P = -\dfrac{3}{2} \implies \dfrac{1}{x_1} + \dfrac{1}{x_2} = \dfrac{S}{P} = \dfrac{-3}{-3/2} = 2\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10521, 'សមីការដឺក្រេទីពីរដែលមានឫស \(x_1 = 3 + \sqrt{5}\) និង \(x_2 = 3 - \sqrt{5}\) គឺ៖', NULL, '["\\(x^2 - 6x - 4 = 0\\)", "\\(x^2 + 6x + 4 = 0\\)", "\\(x^2 - 6x + 4 = 0\\)", "\\(x^2 - 4x + 6 = 0\\)"]', 2, NULL, 2, 'mcq', '\(S = (3+\sqrt{5}) + (3-\sqrt{5}) = 6, P = (3+\sqrt{5})(3-\sqrt{5}) = 9 - 5 = 4\) នាំឱ្យសមីការគឺ \(x^2 - Sx + P = x^2 - 6x + 4 = 0\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10522, 'រកតម្លៃនៃ \(m\) ដើម្បីឱ្យសមីការ \(x^2 - 2(m-1)x + (2m+1) = 0\) មានឫសឌុប៖', NULL, '["\\(m = -4 \\text{ ឬ } m = 0\\)", "\\(m = 1 \\text{ ឬ } m = 2\\)", "\\(m = 2 \\text{ ឬ } m = 4\\)", "\\(m = 0 \\text{ ឬ } m = 4\\)"]', 3, NULL, 2, 'mcq', '\(\Delta'' = (m-1)^2 - (2m+1) = m^2 - 2m + 1 - 2m - 1 = m^2 - 4m = 0 \implies m(m-4) = 0 \implies m = 0\) ឬ \(m = 4\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10523, 'រកលក្ខខណ្ឌនៃ \(m\) ដើម្បីឱ្យសមីការ \(x^2 - 4x + (2m - 6) = 0\) មានឫសពីរមានសញ្ញាផ្ទុយគ្នា៖', NULL, '["\\(m \\le 3\\)", "\\(m > 3\\)", "\\(m < 3\\)", "\\(m < -3\\)"]', 2, NULL, 2, 'mcq', 'សមីការមានឫសផ្ទុយសញ្ញា \(\iff P < 0 \iff 2m - 6 < 0 \iff 2m < 6 \iff m < 3\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10524, 'ចតុកោណកែងមួយមានបណ្តោយវែងជាងទទឹង \(3\text{ m}\) និងមានផ្ទៃក្រឡា \(40\text{ m}^2\)។ រកទទឹងនៃចតុកោណកែងនោះ៖', NULL, '["\\(8\\text{ m}\\)", "\\(5\\text{ m}\\)", "\\(4\\text{ m}\\)", "\\(6\\text{ m}\\)"]', 1, NULL, 2, 'mcq', 'តាងទទឹងជា \(x > 0\) គេបាន \(x(x+3) = 40 \iff x^2 + 3x - 40 = 0 \iff (x-5)(x+8) = 0 \implies x = 5\text{ m}\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10525, 'រកចំនួនកុំផ្លិច \(z\) ដែលផ្ទៀងផ្ទាត់សមីការ \(z + 2\bar{z} = 6 - 3i\)៖', NULL, '["\\(z = 2 - 3i\\)", "\\(z = 3 + 2i\\)", "\\(z = -2 + 3i\\)", "\\(z = 2 + 3i\\)"]', 3, NULL, 3, 'mcq', 'តាង \(z = a + bi\) គេបាន \(a + bi + 2(a - bi) = 3a - bi = 6 - 3i \implies 3a = 6 \implies a = 2\) និង \(-b = -3 \implies b = 3\) នាំឱ្យ \(z = 2 + 3i\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'hard', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10526, 'បើ \(x_1\) និង \(x_2\) ជាឫសនៃសមីការ \(x^2 - 3x + 1 = 0\) គណនាតម្លៃនៃ \(x_1^3 + x_2^3\)៖', NULL, '["\\(18\\)", "\\(21\\)", "\\(27\\)", "\\(15\\)"]', 0, NULL, 3, 'mcq', '\(S = 3, P = 1 \implies x_1^3 + x_2^3 = S(S^2 - 3P) = 3(3^2 - 3\times 1) = 3(9 - 3) = 18\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'hard', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10527, 'បើផលសងរវាងឫសទាំងពីរនៃសមីការ \(x^2 - mx + 8 = 0\) ស្មើនឹង \(2\) (\(x_1 - x_2 = 2\)) រកតម្លៃវិជ្ជមាននៃ \(m\)៖', NULL, '["\\(m = 10\\)", "\\(m = 4\\)", "\\(m = 8\\)", "\\(m = 6\\)"]', 3, NULL, 3, 'mcq', '\((x_1 - x_2)^2 = S^2 - 4P \implies 2^2 = m^2 - 4(8) \iff 4 = m^2 - 32 \iff m^2 = 36 \implies m = 6\) (ព្រោះ \(m > 0\))។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'hard', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10528, 'បើ \(x_1, x_2\) ជាឫសនៃសមីការ \(x^2 - 4x + 2 = 0\) សមីការដឺក្រេទីពីរដែលមានឫស \(y_1 = 2x_1 + 1\) និង \(y_2 = 2x_2 + 1\) គឺ៖', NULL, '["\\(y^2 + 10y + 17 = 0\\)", "\\(y^2 - 10y + 17 = 0\\)", "\\(y^2 - 10y + 9 = 0\\)", "\\(y^2 - 8y + 17 = 0\\)"]', 1, NULL, 3, 'mcq', '\(S_y = 2(x_1+x_2) + 2 = 2(4) + 2 = 10\) និង \(P_y = 4x_1x_2 + 2(x_1+x_2) + 1 = 4(2) + 2(4) + 1 = 17\) នាំឱ្យសមីការគឺ \(y^2 - 10y + 17 = 0\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'hard', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10529, 'រកសំណុំតម្លៃនៃ \(m\) ដើម្បីឱ្យសមីការ \(x^2 - 2(m+1)x + (m+3) = 0\) មានឫសវិជ្ជមានទាំងពីរខុសគ្នា៖', NULL, '["\\(m < -2 \\text{ ឬ } m > 1\\)", "\\(m > 1\\)", "\\(-3 < m < -2\\)", "\\(m > -1\\)"]', 1, NULL, 3, 'mcq', '\(\Delta'' = (m+1)^2 - (m+3) = m^2 + m - 2 > 0 \iff m < -2\) ឬ \(m > 1\); \(P = m+3 > 0 \iff m > -3\); \(S = 2(m+1) > 0 \iff m > -1\)។ ប្រសព្វលក្ខខណ្ឌទាំងបីបាន \(m > 1\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'hard', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10530, 'រកចំនួនកុំផ្លិច \(z\) ដែលផ្ទៀងផ្ទាត់សមភាព \(z^2 = 3 + 4i\)៖', NULL, '["\\(z = 2 + i \\text{ ឬ } z = -2 - i\\)", "\\(z = 3 + 2i \\text{ ឬ } z = -3 - 2i\\)", "\\(z = 1 + 2i \\text{ ឬ } z = -1 - 2i\\)", "\\(z = 2 - i \\text{ ឬ } z = -2 + i\\)"]', 0, NULL, 3, 'mcq', '\(x^2 - y^2 = 3, 2xy = 4, x^2 + y^2 = 5 \implies x^2 = 4 \implies x = \pm 2\)។ ដោយ \(xy = 2 > 0 \implies y = \pm 1\) នាំឱ្យ \(z = \pm(2 + i)\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'hard', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10531, 'រកចំនួនឫសពិតនៃសមីការទ្វេដឺក្រេទីពីរ \(x^4 - 3x^2 - 4 = 0\)៖', NULL, '["\\(1 \\text{ ឫសពិត}\\)", "\\(4 \\text{ ឫសពិត}\\)", "\\(0 \\text{ ឫសពិត}\\)", "\\(2 \\text{ ឫសពិត}\\)"]', 3, NULL, 3, 'mcq', 'តាង \(u = x^2 \ge 0 \implies u^2 - 3u - 4 = 0 \iff (u-4)(u+1) = 0\)។ យក \(u = 4 \implies x^2 = 4 \implies x = \pm 2\) (មាន \(2\) ឫសពិត); \(u = -1 < 0\) គ្មានឫសពិត។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'hard', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10532, 'គ្រាប់បាល់មួយត្រូវបានទាត់ឡើងលើ ដោយកម្ពស់គិតជាម៉ែត្របន្ទាប់ពី \(t\) វិនាទី កំណត់ដោយ \(h(t) = -5t^2 + 20t\)។ តើបន្ទាប់ពីទាត់បានប៉ុន្មានវិនាទី ទើបគ្រាប់បាល់ធ្លាក់មកដល់ដីវិញ?', NULL, '["\\(20\\text{ វិនាទី}\\)", "\\(4\\text{ វិនាទី}\\)", "\\(2\\text{ វិនាទី}\\)", "\\(5\\text{ វិនាទី}\\)"]', 1, NULL, 3, 'mcq', 'គ្រាប់បាល់ធ្លាក់ដល់ដីពេល \(h(t) = 0 \iff -5t(t - 4) = 0 \implies t = 4\text{ s}\) (ព្រោះ \(t > 0\))។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'pisa', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10533, 'សួនផ្កាមួយមានរាងចតុកោណកែងទំហំ \(8\text{ m} \times 6\text{ m}\)។ គេធ្វើផ្លូវដើរព័ទ្ធជុំវិញសួននោះដោយមានទទឹងថេរ \(x\) ស្មើៗគ្នា ធ្វើឱ្យផ្ទៃក្រឡាសរុបរួមទាំងផ្លូវស្មើនឹង \(80\text{ m}^2\)។ រកទទឹងផ្លូវ \(x\)៖', NULL, '["\\(1\\text{ m}\\)", "\\(0.5\\text{ m}\\)", "\\(1.5\\text{ m}\\)", "\\(2\\text{ m}\\)"]', 0, NULL, 3, 'mcq', '\((8 + 2x)(6 + 2x) = 80 \iff 4x^2 + 28x + 48 = 80 \iff 4x^2 + 28x - 32 = 0 \iff x^2 + 7x - 8 = 0 \implies x = 1\text{ m}\) (ព្រោះ \(x > 0\))។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'pisa', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10534, 'សិប្បកម្មមួយលក់ផលិតផលចំនួន \(x\) គ្រឿងក្នុងមួយថ្ងៃ ដោយប្រាក់ចំណេញគិតជាដុល្លារកំណត់ដោយ \(P(x) = -2x^2 + 80x - 300\)។ តើសិប្បកម្មត្រូវលក់ប៉ុន្មានគ្រឿងដើម្បីទទួលបានប្រាក់ចំណេញអតិបរមា?', NULL, '["\\(25\\text{ គ្រឿង}\\)", "\\(20\\text{ គ្រឿង}\\)", "\\(40\\text{ គ្រឿង}\\)", "\\(15\\text{ គ្រឿង}\\)"]', 1, NULL, 3, 'mcq', 'ចំណុចកំពូលនៃប៉ារ៉ាបូលគឺ \(x = -\dfrac{b}{2a} = -\dfrac{80}{2(-2)} = 20\text{ គ្រឿង}\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'pisa', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10535, 'រថយន្តមួយបើកបរលើចម្ងាយផ្លូវ \(120\text{ km}\)។ បើអ្នកបើកបរបង្កើនល្បឿនមធ្យម \(20\text{ km/h}\) នោះពេលវេលាធ្វើដំណើរនឹងថយចុះ \(30\text{ នាទី}\) (\(0.5\text{ h}\))។ រកល្បឿនដើមរបស់រថយន្ត៖', NULL, '["\\(80\\text{ km/h}\\)", "\\(40\\text{ km/h}\\)", "\\(60\\text{ km/h}\\)", "\\(50\\text{ km/h}\\)"]', 2, NULL, 3, 'mcq', '\(\dfrac{120}{v} - \dfrac{120}{v+20} = 0.5 \iff \dfrac{2\,400}{v(v+20)} = 0.5 \iff v^2 + 20v - 4\,800 = 0 \iff (v-60)(v+80) = 0 \implies v = 60\text{ km/h}\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'pisa', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10536, 'ធុងទឹកមួយមានបំពង់បង្ហូរចូលពីរ។ បើបើកទាំងពីរព្រមគ្នា ធុងនឹងពេញក្នុង \(12\) នាទី។ ប្រសិនបើបើកបំពង់ទីមួយតែឯង ត្រូវការពេលយូរជាងបំពង់ទីពីរ \(10\) នាទី។ តើបំពង់ទីពីរចំណាយពេលប៉ុន្មាននាទីទើបបង្ហូរពេញធុងតែឯង?', NULL, '["\\(15\\text{ នាទី}\\)", "\\(30\\text{ នាទី}\\)", "\\(25\\text{ នាទី}\\)", "\\(20\\text{ នាទី}\\)"]', 3, NULL, 3, 'mcq', '\(\dfrac{1}{t} + \dfrac{1}{t+10} = \dfrac{1}{12} \iff \dfrac{2t+10}{t^2+10t} = \dfrac{1}{12} \iff t^2 - 14t - 120 = 0 \iff (t-20)(t+6) = 0 \implies t = 20\text{ នាទី}\)។', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'pisa', 1, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10537, 'គេឱ្យសមីការដឺក្រេទីពីរ \(2x^2 - 8x + 6 = 0\)។ ចូរគណនាផលបូកឫស \(S = x_1 + x_2\), ផលគុណឫស \(P = x_1 x_2\) និងរកឫសទាំងពីរ \(x_1, x_2\) នៃសមីការ។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាផលបូកឫស \(S = -\dfrac{b}{a} = -\dfrac{-8}{2} = 4\) (1 ពិន្ទុ)
គណនាផលគុណឫស \(P = \dfrac{c}{a} = \dfrac{6}{2} = 3\) (1 ពិន្ទុ)
បំប្លែងសមីការ \(x^2 - 4x + 3 = 0\) ឬដាក់ជាផលគុណកត្តា \((x-1)(x-3) = 0\) (2 ពិន្ទុ)
សន្និដ្ឋានឫសទាំងពីរគឺ \(x_1 = 1\) និង \(x_2 = 3\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'easy', 0, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10538, 'គេឱ្យចំនួនកុំផ្លិច \(z_1 = 3 + 2i\) និង \(z_2 = 1 - i\)។
ក. គណនាផលគុណ \(z_1 \cdot z_2\)
ខ. គណនាផលចែក \(\dfrac{z_1}{z_2}\) រួចសរសេរជាទម្រង់ពីជគណិត \(a + bi\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនាផលគុណ \(z_1 \cdot z_2 = (3+2i)(1-i) = 3 - 3i + 2i - 2i^2 = 5 - i\) (2 ពិន្ទុ)
គុណភាគយក និងភាគបែងនឹងកុំផ្លិចឆ្លាស់ \(\bar{z}_2 = 1 + i\) (1 ពិន្ទុ)
គណនាភាគយក \((3+2i)(1+i) = 1 + 5i\) និងភាគបែង \(1^2 - i^2 = 2\) (1 ពិន្ទុ)
សន្និដ្ឋានផលចែក \(\dfrac{z_1}{z_2} = \dfrac{1}{2} + \dfrac{5}{2}i\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 0, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10539, 'ដោះស្រាយសមីការដឺក្រេទីពីរ \(3x^2 - 5x + 1 = 0\)។
ក. គណនាឌីសគ្រីមីណង់ \(\Delta\)
ខ. កំណត់ធម្មជាតិនៃឫស
គ. រកតម្លៃឫសទាំងពីរនៃសមីការ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់មេគុណ \(a=3, b=-5, c=1\) រួចគណនា \(\Delta = (-5)^2 - 4(3)(1) = 25 - 12 = 13\) (2 ពិន្ទុ)
ដោយ \(\Delta = 13 > 0\) នាំឱ្យសមីការមានឫសពីរជាចំនួនពិតខុសគ្នា (1 ពិន្ទុ)
អនុវត្តរូបមន្តឫស \(x = \dfrac{-b \pm \sqrt{\Delta}}{2a} = \dfrac{5 \pm \sqrt{13}}{6}\) (1 ពិន្ទុ)
សន្និដ្ឋានសំណុំចម្លើយ \(S = \left\{\dfrac{5 - \sqrt{13}}{6}, \dfrac{5 + \sqrt{13}}{6}\right\}\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 0, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10540, 'ដោះស្រាយសមីការ \(x^2 - 4x + 13 = 0\) ក្នុងសំណុំចំនួនកុំផ្លិច \(\mathbb{C}\)។
ក. គណនាឌីសគ្រីមីណង់សម្រួល \(\Delta''\)
ខ. រកឫសកុំផ្លិចទាំងពីរ \(x_1\) និង \(x_2\)
គ. គណនាម៉ូឌុលនៃឫសនីមួយៗ \(|x_1|\) និង \(|x_2|\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ \(b'' = -2\) រួចគណនា \(\Delta'' = (-2)^2 - 1(13) = 4 - 13 = -9 = (3i)^2\) (2 ពិន្ទុ)
ទាញរកឫសកុំផ្លិចទាំងពីរ \(x = \dfrac{-b'' \pm \sqrt{\Delta''}}{a} = 2 \pm 3i\) (1 ពិន្ទុ)
គណនាម៉ូឌុល \(|x_1| = \sqrt{2^2 + 3^2} = \sqrt{4 + 9} = \sqrt{13}\) (1 ពិន្ទុ)
គណនាម៉ូឌុល \(|x_2| = \sqrt{2^2 + (-3)^2} = \sqrt{13}\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 0, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10541, 'គេឱ្យសមីការ \(x^2 - 6x + 4 = 0\) មានឫសពីរគឺ \(x_1\) និង \(x_2\)។ ដោយមិនបាច់ដោះស្រាយសមីការ ចូរគណនាតម្លៃនៃ៖
ក. \(A = x_1^2 + x_2^2\)
ខ. \(B = \dfrac{1}{x_1} + \dfrac{1}{x_2}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់ផលបូកឫស \(S = x_1 + x_2 = 6\) និងផលគុណឫស \(P = x_1 x_2 = 4\) (1 ពិន្ទុ)
បំប្លែងកន្សោម \(A = (x_1 + x_2)^2 - 2x_1 x_2 = S^2 - 2P\) (1 ពិន្ទុ)
គណនា \(A = 6^2 - 2(4) = 36 - 8 = 28\) (1 ពិន្ទុ)
បំប្លែងកន្សោម \(B = \dfrac{x_1 + x_2}{x_1 x_2} = \dfrac{S}{P}\) (1 ពិន្ទុ)
គណនា \(B = \dfrac{6}{4} = \dfrac{3}{2}\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'medium', 0, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10542, 'គេឱ្យសមីការដឺក្រេទីពីរ \((m-1)x^2 - 2mx + m + 2 = 0\) ដែល \(m\) ជាប៉ារ៉ាម៉ែត្រពិត។
ក. រកលក្ខខណ្ឌនៃ \(m\) ដើម្បីឱ្យសមីការនេះជាសមីការដឺក្រេទីពីរ
ខ. រកតម្លៃនៃ \(m\) ដើម្បីឱ្យសមីការមានឫសឌុប រួចកំណត់ឫសឌុបនោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'លក្ខខណ្ឌដើម្បីជាសមីការដឺក្រេទីពីរគឺ \(a \neq 0 \iff m - 1 \neq 0 \iff m \neq 1\) (1 ពិន្ទុ)
គណនា \(\Delta'' = (-m)^2 - (m-1)(m+2) = m^2 - (m^2 + m - 2) = -m + 2\) (2 ពិន្ទុ)
សមីការមានឫសឌុបកាលណា \(\Delta'' = 0 \iff -m + 2 = 0 \iff m = 2\) (ផ្ទៀងផ្ទាត់ \(m \neq 1\)) (1 ពិន្ទុ)
គណនាឫសឌុប \(x_0 = -\dfrac{b''}{a} = \dfrac{2}{2-1} = 2\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'hard', 0, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10543, 'គេឱ្យសមីការ \(2x^2 - 4x - 1 = 0\) មានឫសពីរគឺ \(x_1\) និង \(x_2\)។
ក. គណនាផលបូក \(S\) និងផលគុណ \(P\) នៃឫស
ខ. គណនាតម្លៃនៃ \(x_1^3 + x_2^3\)
គ. គណនាតម្លៃនៃ \(|x_1 - x_2|\)។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា \(S = -\dfrac{-4}{2} = 2\) និង \(P = -\dfrac{1}{2}\) (1 ពិន្ទុ)
សរសេររូបមន្ត \(x_1^3 + x_2^3 = S^3 - 3SP\) (1 ពិន្ទុ)
គណនា \(x_1^3 + x_2^3 = 2^3 - 3(2)\left(-\dfrac{1}{2}\right) = 8 + 3 = 11\) (1 ពិន្ទុ)
គណនា \((x_1 - x_2)^2 = S^2 - 4P = 2^2 - 4\left(-\dfrac{1}{2}\right) = 4 + 2 = 6\) (1 ពិន្ទុ)
សន្និដ្ឋាន \(|x_1 - x_2| = \sqrt{6}\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'hard', 0, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10544, 'រកចំនួនកុំផ្លិច \(z = x + yi\) (\(x, y \in \mathbb{R}\)) ដែលផ្ទៀងផ្ទាត់សមភាព \(z^2 = 21 - 20i\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ពន្លាត \(z^2 = (x+yi)^2 = (x^2 - y^2) + 2xyi\) (1 ពិន្ទុ)
ផ្ទឹមផ្នែកពិត និងផ្នែកនិម្មិត៖ \(x^2 - y^2 = 21\) និង \(2xy = -20 \iff xy = -10\) (1 ពិន្ទុ)
គណនាម៉ូឌុលការេ៖ \(x^2 + y^2 = \sqrt{21^2 + (-20)^2} = \sqrt{441 + 400} = \sqrt{841} = 29\) (1 ពិន្ទុ)
បូកសមីការបាន \(2x^2 = 50 \iff x^2 = 25 \implies x = \pm 5\) រួចទាញបាន \(y = \mp 2\) (ព្រោះ \(xy < 0\)) (1 ពិន្ទុ)
សន្និដ្ឋានចំនួនកុំផ្លិចដែលត្រូវរកគឺ \(z_1 = 5 - 2i\) និង \(z_2 = -5 + 2i\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'hard', 0, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10545, 'គេឱ្យសមីការ \(x^2 - 2(m-1)x + 2m - 5 = 0\)។ រកគ្រប់តម្លៃពិតនៃ \(m\) ដើម្បីឱ្យសមីការមាន៖
ក. ឫសពីរជាចំនួនពិតវិជ្ជមានទាំងពីរ
ខ. ឫសពីរមានសញ្ញាផ្ទុយគ្នា។', NULL, '[]', 0, NULL, 5, 'writing', 'គណនា \(\Delta'' = (m-1)^2 - (2m - 5) = m^2 - 4m + 6 = (m-2)^2 + 2 > 0\) គ្រប់ \(m \in \mathbb{R}\) សមីការតែងមានឫសពីរខុសគ្នាជានិច្ច (1 ពិន្ទុ)
កំណត់ផលបូក \(S = 2(m-1)\) និងផលគុណ \(P = 2m - 5\) (1 ពិន្ទុ)
លក្ខខណ្ឌឫសវិជ្ជមានទាំងពីរ៖ \(S > 0\) និង \(P > 0 \iff m - 1 > 0\) និង \(2m - 5 > 0\) (1 ពិន្ទុ)
ទាញបាន \(m > 1\) និង \(m > \dfrac{5}{2} \implies m > \dfrac{5}{2}\) (1 ពិន្ទុ)
លក្ខខណ្ឌឫសផ្ទុយសញ្ញា៖ \(P < 0 \iff 2m - 5 < 0 \implies m < \dfrac{5}{2}\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'hard', 0, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10546, 'ស្ពានយោងមួយមានខ្សែខ្សែកោងរាងជាប៉ារ៉ាបូលដែលមានសមីការ \(y = \dfrac{1}{100}x^2\) ធៀបនឹងប្រព័ន្ធកូអរដោណេដែលមានគល់នៅចំណុចកណ្តាលទាបបំផុតនៃខ្សែ។
ក. បើសសរស្ពានទាំងសងខាងស្ថិតនៅចម្ងាយ \(60\text{ m}\) ពីចំណុចកណ្តាល (\(x = \pm 60\)) រកកម្ពស់សសរស្ពាន \(y\)។
ខ. រកចម្ងាយផ្តេកពីចំណុចកណ្តាលទៅចំណុចខ្សែស្ពានដែលមានកម្ពស់ \(16\text{ m}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់សមីការខ្សែស្ពាន \(y = \dfrac{1}{100}x^2\) (1 ពិន្ទុ)
ជំនួស \(x = 60\) គណនាកម្ពស់សសរ \(y = \dfrac{1}{100}(60)^2 = \dfrac{3\,600}{100} = 36\text{ m}\) (2 ពិន្ទុ)
សរសេរសមីការកម្ពស់ \(16\text{ m}\)៖ \(\dfrac{1}{100}x^2 = 16 \iff x^2 = 1\,600\) (1 ពិន្ទុ)
ដោះស្រាយបាន \(x = \pm 40\) នាំឱ្យចម្ងាយផ្តេកពីចំណុចកណ្តាលគឺ \(40\text{ m}\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'pisa', 0, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10547, 'កសិករម្នាក់មានរបងលួសប្រវែង \(100\text{ m}\) ដើម្បីធ្វើរបងព័ទ្ធដីចិញ្ចឹមមាន់រាងចតុកោណកែងមួយជាប់នឹងជញ្ជាំងថ្មត្រង់មួយ (មិនបាច់ព័ទ្ធផ្នែកខាងជញ្ជាំងទេ)។
ក. តាង \(x\) ជាទទឹងនៃដីចតុកោណកែង (ជ្រុងកែងនឹងជញ្ជាំង)។ សរសេរបណ្តោយនៃដីជាអនុគមន៍នៃ \(x\)។
ខ. បង្ហាញថាកន្សោមផ្ទៃក្រឡាដីគឺ \(A(x) = -2x^2 + 100x\)។
គ. រកវិមាត្រ \(x\) ដើម្បីឱ្យផ្ទៃក្រឡាដីធំជាងគេអតិបរមា រួចគណនាផ្ទៃក្រឡាអតិបរមានោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់បណ្តោយដី \(L = 100 - 2x\) (1 ពិន្ទុ)
ទាញរកផ្ទៃក្រឡា \(A(x) = x \cdot L = x(100 - 2x) = -2x^2 + 100x\) (1 ពិន្ទុ)
រកចំណុចកំពូលនៃប៉ារ៉ាបូល \(x = -\dfrac{b}{2a} = -\dfrac{100}{2(-2)} = 25\text{ m}\) (1 ពិន្ទុ)
គណនាបណ្តោយត្រូវគ្នា \(L = 100 - 2(25) = 50\text{ m}\) (1 ពិន្ទុ)
គណនាផ្ទៃក្រឡាអតិបរមា \(A_{\max} = 25 \times 50 = 1\,250\text{ m}^2\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'pisa', 0, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10548, 'គ្រាប់រ៉ុក្កែតកម្សាន្តមួយត្រូវបានបាញ់បង្ហោះឡើងលើត្រង់។ កម្ពស់របស់វាគិតជាម៉ែត្របន្ទាប់ពីបាញ់បាន \(t\) វិនាទី កំណត់ដោយសមីការ \(h(t) = -5t^2 + 60t + 5\)។
ក. រកកម្ពស់ដើមរបស់គ្រាប់រ៉ុក្កែតនៅពេលចាប់ផ្តើមបាញ់ (\(t = 0\))
ខ. រកពេលវេលា \(t\) ដែលរ៉ុក្កែតឡើងដល់កម្ពស់អតិបរមា និងគណនាកម្ពស់អតិបរមានោះ
គ. រកពេលវេលាដែលរ៉ុក្កែតធ្លាក់ដល់ដី (\(h(t) = 0\)) ដោយយក \(\sqrt{37} \approx 6.08\)។', NULL, '[]', 0, NULL, 5, 'writing', 'នៅពេល \(t = 0\) កម្ពស់ដើមគឺ \(h(0) = 5\text{ m}\) (1 ពិន្ទុ)
រកពេលវេលាឡើងដល់កំពូល \(t = -\dfrac{60}{2(-5)} = 6\text{ វិនាទី}\) (1 ពិន្ទុ)
គណនាកម្ពស់អតិបរមា \(h(6) = -5(36) + 60(6) + 5 = 185\text{ m}\) (1 ពិន្ទុ)
សរសេរសមីការធ្លាក់ដល់ដី \(-5t^2 + 60t + 5 = 0 \iff t^2 - 12t - 1 = 0 \implies \Delta'' = 37\) (1 ពិន្ទុ)
គណនាពេលវេលាធ្លាក់ដល់ដី \(t = 6 + \sqrt{37} \approx 6 + 6.08 = 12.08\text{ វិនាទី}\) (1 ពិន្ទុ)', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'pisa', 0, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10549, 'សិស្សមួយក្រុមបានជួលរថយន្តក្រុងមួយគ្រឿងក្នុងតម្លៃសរុប \(360\) ដុល្លារ ដោយចែករំលែកប្រាក់ថ្លៃជួលស្មើៗគ្នា។ នៅថ្ងៃចេញដំណើរ មានសិស្ស \(3\) នាក់អវត្តមាន នាំឱ្យសិស្សម្នាក់ៗដែលបានទៅត្រូវបង់ប្រាក់បន្ថែម \(2\) ដុល្លារ។
ក. តាង \(n\) ជាចំនួនសិស្សសរុបដែលបានគ្រោងទុកដំបូង។ សរសេរសមីការតាងចំណោទនេះ
ខ. បង្ហាញថាសមីការបង្រួមទៅជា \(n^2 - 3n - 540 = 0\)
គ. រកចំនួនសិស្សដែលបានគ្រោងទុកដំបូង \(n\) និងចំនួនសិស្សដែលបានទៅជាក់ស្តែង។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង \(n\) ជាចំនួនសិស្សគ្រោងទុកដំបូង សមីការគឺ \(\dfrac{360}{n-3} - \dfrac{360}{n} = 2\) (1 ពិន្ទុ)
តម្រូវភាគបែងរួម៖ \(\dfrac{360n - 360(n-3)}{n(n-3)} = 2 \iff \dfrac{1\,080}{n(n-3)} = 2\) (1 ពិន្ទុ)
បង្រួញសមីការបាន \(2(n^2 - 3n) = 1\,080 \iff n^2 - 3n - 540 = 0\) (1 ពិន្ទុ)
ដោះស្រាយសមីការបាន \((n - 27)(n + 20) = 0 \implies n = 27\) (ព្រោះ \(n > 0\)) (1 ពិន្ទុ)
សន្និដ្ឋានចំនួនសិស្សគ្រោងទុកដំបូងគឺ \(27\) នាក់ និងសិស្សទៅជាក់ស្តែងគឺ \(27 - 3 = 24\) នាក់ (1 ពិន្ទុ)', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', 'pisa', 0, '10', 'សមីការដឺក្រេទី 2 មានមួយអញ្ញាត', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 10550, 'រោងពុម្ពមួយបោះពុម្ពសៀវភៅដោយមានថ្លៃដើមសរុប \(C(x) = 500 + 4x\) (ដុល្លារ) និងចំណូលសរុបពីការលក់ \(R(x) = 24x - 0.02x^2\) (ដុល្លារ) ចំពោះសៀវភៅចំនួន \(x\) ក្បាល។
ក. រកកន្សោមប្រាក់ចំណេញ \(P(x) = R(x) - C(x)\)
ខ. រកចំនួនសៀវភៅដែលត្រូវបោះពុម្ព និងលក់ដើម្បីទទួលបានប្រាក់ចំណេញអតិបរមា
គ. គណនាប្រាក់ចំណេញអតិបរមានោះ។', NULL, '[]', 0, NULL, 5, 'writing', 'កំណត់កន្សោមប្រាក់ចំណេញ \(P(x) = (24x - 0.02x^2) - (500 + 4x) = -0.02x^2 + 20x - 500\) (1 ពិន្ទុ)
ចំណុចអតិបរមាសម្រេចបានត្រង់កំពូលនៃប៉ារ៉ាបូល \(x = -\dfrac{b}{2a}\) (1 ពិន្ទុ)
គណនា \(x = -\dfrac{20}{2(-0.02)} = \dfrac{20}{0.04} = 500\text{ ក្បាល}\) (1 ពិន្ទុ)
